    ('e5079e17-27bc-4c6a-897d-68134cf661c7'::uuid, 'site_type', 'Well', 'Megalithic structures', 'fields-wd1-2026-09-26d-s021-rollback:e5079e17-27bc-4c6a-897d-68134cf661c7:site_type', 'rollback of fields-wd1-2026-09-26d-s021: site_type ''Megalithic structures'' restored on Sacred Pit of Garlo', '[{"source": "https://www.megalithic.co.uk/article.php?sid=35643", "url": "https://www.megalithic.co.uk/article.php?sid=35643", "quote": "Type: Holy Well or Sacred Spring", "outcome": "found"}, {"source": "https://travelbulgaria.news/temple-garlo-oldest-structures-balkans/", "url": "https://travelbulgaria.news/temple-garlo-oldest-structures-balkans/", "quote": "For over 3000 years, the ancient well near the village of Garlo has been hiding its mystical secrets.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Sacred_pit_of_Garlo", "url": "https://en.wikipedia.org/wiki/Sacred_pit_of_Garlo", "quote": "According to the memories of local residents, signs are carved in the surrounding rocks, and there is a small stone basin near the temple well.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0001)", "decision": "replace", "status": "MISSING", "reasoning": "The Megalithic Portal classes the Sacred Pit of Garlo as a holy well, Travel Bulgaria News calls it the ancient (temple) well near Garlo and Wikipedia a temple well: a domed underground chamber built over a 5 m well shaft. Well is the most specific type for what the sources say it is; ''megalithic'' only describes its masonry.", "value_page": null}]'::jsonb),
