    ('e6de5091-b046-45e8-bb6a-a81c99b2fbe2'::uuid, 'period_start', '-1279', '-3000', 'fields-wd1-2026-09-26d-s021-rollback:e6de5091-b046-45e8-bb6a-a81c99b2fbe2:period_start', 'rollback of fields-wd1-2026-09-26d-s021: period_start ''-3000'' restored on The Ramesseum', '[{"source": "https://egymonuments.gov.eg/en/monuments/the-ramesseum-the-temple-of-ramses-ii", "url": "https://egymonuments.gov.eg/en/monuments/the-ramesseum-the-temple-of-ramses-ii", "quote": "King Ramses II (c.1279-1213 BC), the most famous king of ancient Egypt (who fought a battle against the Hittites), built the Ramesseum Temple, a funerary temple built of sandstone", "outcome": "found"}, {"source": "https://www.ancient-egypt-online.com/ramesseum.html", "url": "https://www.ancient-egypt-online.com/ramesseum.html", "quote": "The last great pharaoh of Egypt, Ramesses II, spent 20 years building the Ramesseum during his unusually long 67 year reign. Ramesses II ruled during the height of Ancient Egyptian power and glory during the 13th century BC from 1279-1213 BC.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Ramesseum", "url": "https://en.wikipedia.org/wiki/Ramesseum", "quote": "Built 13th century BC Built by Ramesses II", "outcome": "found"}, {"source": "WD1 decision (counted, round 2, wd1-r2-b0001)", "decision": "replace", "status": "MISSING", "reasoning": "Egypt''s Ministry of Tourism and Antiquities, Ancient Egypt Online and English Wikipedia all date the Ramesseum to its builder Ramesses II, whose reign began c. 1279 BC (13th century BC); construction cannot start before 1279 BC, so the stored -3000 (3000-1500 BC bucket) is wrong and the start is c. 1279 BC in the 1500-500 BC bucket.", "value_page": null}]'::jsonb),
